import React, { useState, useEffect, useRef, useCallback } from 'react';
import { useLocation } from 'react-router-dom';
import styles from '../css/chat.module.css';

const Chat = () => {
  const location = useLocation();
  const { personality, name: chatbotName = '챗봇' } = location.state || {};
  const [userInput, setUserInput] = useState('');
  const [currentDateTime, setCurrentDateTime] = useState('');
  const [error, setError] = useState(null);
  const [isRecording, setIsRecording] = useState(false);
  const [isProcessingResponse, setIsProcessingResponse] = useState(false);
  const [audioHtml, setAudioHtml] = useState(null);
  const [messages, setMessages] = useState([]);
  const chatEndRef = useRef(null);
  const mediaRecorderRef = useRef(null);
  const audioChunksRef = useRef([]);
  const inputRef = useRef(null); // 입력 필드 참조

  // 현재 날짜와 시간 가져오기
  const getCurrentDateTime = () => {
    const now = new Date();
    const date = now.toLocaleDateString('ko-KR', {
      year: 'numeric',
      month: 'long',
      day: 'numeric',
      weekday: 'long',
    });
    const time = now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
    return `${date} ${time}`;
  };

  // 시간만 가져오기
  const getTimeOnly = () => {
    const now = new Date();
    return now.toLocaleTimeString('ko-KR', {
      hour: '2-digit',
      minute: '2-digit',
      hour12: false,
    });
  };

  const addEventToGoogleCalendar = async (eventDetails) => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/add-calendar-event`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(eventDetails),
      });
  
      if (!response.ok) {
        throw new Error('일정 추가 오류');
      }
  
      const data = await response.json();
      console.log('구글 캘린더에 일정이 추가되었습니다:', data);
    } catch (error) {
      console.error('구글 캘린더에 일정 추가 중 오류 발생:', error);
    }
  };

  // 메시지 추가 (중복 방지)
  const addMessage = (sender, message, time) => {
    setMessages((prevMessages) => {
      if (prevMessages.some((msg) => msg.sender === sender && msg.message === message && msg.time === time)) {
        return prevMessages; // 중복 메시지 방지
      }
      return [...prevMessages, { sender, message, time }];
    });
  };

  // 일정 삭제 요청
  const deleteEventFromGoogleCalendar = async (eventId) => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/delete-calendar-event`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ eventId }),
      });

      if (!response.ok) {
        throw new Error('일정 삭제 오류');
      }

      const data = await response.json();
      console.log('구글 캘린더에서 일정이 삭제되었습니다:', data);
    } catch (error) {
      console.error('구글 캘린더에서 일정 삭제 중 오류 발생:', error);
    }
  };


  let isNotified = false; // 알림이 이미 설정되었는지 확인

  // 메시지에서 일정 정보 추출
  const extractEventDetailsFromMessage = (message) => {
    const regex = /일정 삭제:\s*(.*)\s*(\d{4}-\d{2}-\d{2})\s*(\d{1,2}:\d{2})\s*~\s*(\d{1,2}:\d{2})/;
    const match = message.match(regex);

    if (match) {
      const event = match[1].trim();
      const startDateTime = `${match[2]}T${match[3]}:00`;
      const endDateTime = `${match[2]}T${match[4]}:00`;

      return {
        event,
        start: { dateTime: startDateTime },
        end: { dateTime: endDateTime },
      };
    }

    return null;
  };

  // extractEventIdFromMessage 함수 (메시지에서 eventId 추출)
  const extractEventIdFromMessage = (message) => {
    const regex = /일정 삭제\s*(?:https?:\/\/[^ ]+eid=([A-Za-z0-9_-]+))/;
    const match = message.match(regex);
    return match ? match[1] : null;
  };

  const handleScheduleNotification = (message) => {
    if (message.includes("일정 삭제")) {
      const eventDetails = extractEventDetailsFromMessage(message); // 메시지에서 일정 정보 추출
      if (eventDetails) {
        findAndDeleteEventFromGoogleCalendar(eventDetails);  // 일정 삭제 호출
        addMessage(chatbotName, `${eventDetails.event} 일정 삭제가 완료되었습니다.`, getTimeOnly()); // 챗봇의 답변 추가
      } else {
        addMessage(chatbotName, "일정을 찾을 수 없습니다. 올바른 형식으로 다시 시도해주세요.", getTimeOnly());
      }
    }

    // 이미 알림이 설정되었으면 실행하지 않음
    if (isNotified) return;

    // "오늘" 뒤에 공백이 있을 수도 있고 없을 수도 있으므로 그에 맞는 정규식 적용
    const regex = /오늘\s*(.*?)(\d{1,2}시 \d{1,2}분)/;
    const match = message.match(regex);

    if (match) {
      const event = match[1].trim(); // "오늘"과 시간 사이의 텍스트 (예: 수업, 병원)
      const time = match[2];  // 시간 (예: 15시 39분)

      // 시간 추출
      const [hour, minute] = time.split('시').map(str => parseInt(str.replace('분', '').trim(), 10));
      
      const now = new Date();
      const scheduleTime = new Date(now);
      scheduleTime.setHours(hour, minute, 0, 0);

      const eventDetails = {
        summary: event,
        description: `오늘 ${event}`,
        start: {
          dateTime: scheduleTime.toISOString(),
          timeZone: 'Asia/Seoul',
        },
        end: {
          dateTime: new Date(scheduleTime.getTime() + 60 * 60 * 1000).toISOString(), // 1시간
          timeZone: 'Asia/Seoul',
        },
      };
  
      addEventToGoogleCalendar(eventDetails);  // 일정 추가 함수 호출

      const notifyTime = new Date(scheduleTime.getTime() - 30 * 60 * 1000); // 30분 전
      const timeDifference = notifyTime.getTime() - now.getTime();

      if (timeDifference > 0) {
        isNotified = true;  // 알림 설정
        setTimeout(() => {
          alert(`일정 : ${event} 30분 전입니다!`);
          sendVoiceNotification(`일정 : ${event} 30분 전입니다!`);
        }, timeDifference);
      }
    }
  };

  // 일정 삭제 함수
  const findAndDeleteEventFromGoogleCalendar = async (eventDetails) => {
    try {
      // 구글 캘린더에서 일정 검색 (예: 날짜 및 시간 기준으로 검색)
      const events = await searchEventInGoogleCalendar(eventDetails);
      if (events.length > 0) {
        const eventId = events[0].id;  // 첫 번째 일정을 선택 (여러 개의 일정이 있을 수 있음)
        await deleteEventFromGoogleCalendar(eventId);  // 일정 삭제
      } else {
        console.log('일정을 찾을 수 없습니다.');
      }
    } catch (error) {
      console.error('일정 삭제 오류:', error);
    }
  };


  // 음성 알림
  const sendVoiceNotification = async (text) => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/whisper-tts`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ text: text }),
      });

      if (!response.ok) {
        throw new Error('음성 알림 전송 오류');
      }

      const data = await response.json();
      const newAudioHtml = data.audio_html;
      setAudioHtml(newAudioHtml);
    } catch (error) {
      console.error('음성 알림 오류:', error);
      setError(error.message);
    }
  };

  const searchEventInGoogleCalendar = async (eventDetails) => {
    try {
      const response = await fetch(`${process.env.REACT_APP_API_URL}/search-calendar-event`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ start: eventDetails.start.dateTime, end: eventDetails.end.dateTime }),
      });
  
      if (!response.ok) {
        throw new Error('일정 검색 오류');
      }
  
      const data = await response.json();
      return data.items || []; // 일정이 있을 경우 리턴
    } catch (error) {
      console.error('구글 캘린더에서 일정 검색 중 오류 발생:', error);
      return [];
    }
  };

  // 음성 녹음 시작
  const startRecording = () => {
    if (isRecording || isProcessingResponse) return;

    audioChunksRef.current = [];

    if (navigator.mediaDevices && navigator.mediaDevices.getUserMedia) {
      navigator.mediaDevices.getUserMedia({ audio: true })
        .then((stream) => {
          mediaRecorderRef.current = new MediaRecorder(stream);

          mediaRecorderRef.current.ondataavailable = (event) => {
            audioChunksRef.current.push(event.data);
          };

          mediaRecorderRef.current.onstop = async () => {
            if (isProcessingResponse) return; // 중복 처리 방지
            setIsProcessingResponse(true);

            const audioBlob = new Blob(audioChunksRef.current, { type: 'audio/mp3' });
            const audioData = await audioBlob.arrayBuffer();
            const formData = new FormData();
            formData.set('chatbot_name', chatbotName);
            formData.set('personality', personality);
            formData.set('file', new Blob([audioData]), 'audio.mp3');

            try {
              const response = await fetch(`${process.env.REACT_APP_API_URL}/chat-audio`, {
                method: 'POST',
                body: formData,
              });

              if (!response.ok) {
                throw new Error('음성 파일 전송 오류');
              }

              const data = await response.json();
              const chatbotMessage = data.response;
              const newAudioHtml = data.audio_html;
              const recognizedText = data.transcribed_text;

              const sentTime = getTimeOnly();
              addMessage('사용자', recognizedText, sentTime);

              const receivedTime = getTimeOnly();
              addMessage(chatbotName, chatbotMessage, receivedTime);

              handleScheduleNotification(recognizedText);

              setAudioHtml(newAudioHtml);
              setUserInput('');
            } catch (error) {
              setError(error.message);
            } finally {
              setIsProcessingResponse(false);
            }
          };

          mediaRecorderRef.current.start();
          setIsRecording(true);
        })
        .catch((err) => {
          console.error('녹음 권한을 요청할 수 없습니다.', err);
        });
    }
  };

  // 음성 녹음 중지
  const stopRecording = () => {
    if (!isRecording) return;

    if (mediaRecorderRef.current) {
      mediaRecorderRef.current.stop();
    }
    setIsRecording(false);
    audioChunksRef.current = [];
  };

  // 텍스트 메시지 전송
  const handleSendMessage = async () => {
    if (isRecording || isProcessingResponse || userInput.trim() === '') return;

    const sentTime = getTimeOnly();
    addMessage('사용자', userInput, sentTime);
    setUserInput('');

    handleScheduleNotification(userInput); // 일정 알림 처리

    try {
      setIsProcessingResponse(true);
      const response = await fetch(`${process.env.REACT_APP_API_URL}/chat`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chatbotName: chatbotName,
          user_input: userInput,
          personality: personality,
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.detail || '서버 응답 오류');
      }

      const data = await response.json();
      const chatbotMessage = data.response;
      const newAudioHtml = data.audio_html;

      addMessage(chatbotName, chatbotMessage, getTimeOnly());
      setAudioHtml(newAudioHtml);
    } catch (error) {
      console.error('Error fetching chatbot response:', error);
      setError(error.message);
    } finally {
      setIsProcessingResponse(false);
    }

    setTimeout(() => {
      inputRef.current?.focus();
    }, 100);
  };

  // Enter 키 눌렀을 때 메시지 전송
  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      handleSendMessage();
    }
  };

  // 에러 메시지 표시
  const displayErrorMessage = useCallback(() => {
    return error ? <div className={styles.errorMessage}>{error}</div> : null;
  }, [error]);

  // 채팅 기록 가져오기
  useEffect(() => {
    const interval = setInterval(() => {
      setCurrentDateTime(getCurrentDateTime());
    }, 1000);
    return () => clearInterval(interval);
  }, []);

  // 채팅 기록에 변화가 있을 때 자동으로 스크롤
  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages]);

  return (
    <div className={styles.chatContainer}>
      <div className={styles.chatDataTime}>
        <strong>{currentDateTime}</strong>
      </div>
      <div className={styles.chatHistory}>
        {messages.map((msg, index) => (
          <div
            key={index}
            className={msg.sender === '사용자' ? styles.chatMessageUser : styles.chatMessageChatbot}
          >
            <strong>{msg.sender === '사용자' ? '사용자' : chatbotName}:</strong>
            <div>{msg.message}</div>
            <div className={msg.sender === '사용자' ? styles.chatTimeUser : styles.chatTimeChatbot}>
              <em>{msg.time}</em>
            </div>
          </div>
        ))}
        <div ref={chatEndRef} />
      </div>
      <div className={styles.chatInputArea}>
        <input
          ref={inputRef}
          type="text"
          value={userInput}
          onChange={(e) => setUserInput(e.target.value)}
          onKeyDown={handleKeyDown}
        />
        <button
          className={styles.chatSendButton}
          onClick={handleSendMessage}
          disabled={isRecording || isProcessingResponse}
        >
          전송
        </button>
        <button
          className={styles.voiceButton}
          onClick={isRecording ? stopRecording : startRecording}
        >
          {isRecording ? '녹음 중지' : '음성 인식 시작'}
        </button>
      </div>
      {displayErrorMessage()}
      {!isRecording && !isProcessingResponse && audioHtml && userInput.trim() === '' && (
        <div dangerouslySetInnerHTML={{ __html: audioHtml }} />
      )}
    </div>
  );
};

export default Chat;
